UD_MARKERS = [('SALIDA Y META', 4.636620619146021, -74.18557454188503), ('POSO #1', 4.63595056124937, -74.1856794873719), ('ZONA PRIMEROS AUXILIOS', 4.636123131678395, -74.18533461349806), ('POSO #2', 4.636256731394789, -74.18510720405932), ('ZONA DE CALENTAMIENTO', 4.636626838453369, -74.1859896428246), ('STANTS PATROCINADORES', 4.636662051856271, -74.18528672971253), ('RUTA DE EVACUACION', 4.637173704522139, -74.1853311565425), ('RUTA DE EVACUACION', 4.635492678920779, -74.18533897090154)]
