# LOGOS SIN FONDO
# ============================================================

@st.cache_data(show_spinner=False)
def transparent_logo(path_string, modified):
    """
    Conserva imágenes transparentes y elimina fondos
    blancos sencillos conectados con los bordes.

    No modifica el archivo original.
    """

    path = Path(path_string)

    with Image.open(path) as original:
        image = original.convert("RGBA")

    if image.width > 1500 or image.height > 1500:
        image.thumbnail(
            (1500, 1500),
            Image.Resampling.LANCZOS,
        )

    # Si ya existe transparencia, respetarla.
    if image.getchannel("A").getextrema()[0] == 255:

        width, height = image.size

        corners = [
            (0, 0),
            (width - 1, 0),
            (0, height - 1),
            (width - 1, height - 1),
        ]

        for point in corners:

            r, g, b, alpha = image.getpixel(point)

            # Solo intentar quitar fondos claros.
            if (
                min(r, g, b) >= 225
                and max(r, g, b) - min(r, g, b) <= 22
            ):

                ImageDraw.floodfill(
                    image,
                    point,
                    (255, 255, 255, 0),
                    thresh=32,
                )

    buffer = BytesIO()

    image.save(
        buffer,
        format="PNG",
    )

    return buffer.getvalue()


def show_logo(path, width=None, full_width=False):

    path = Path(path)

    if not path.is_file():
        return

    data = transparent_logo(
        str(path),
        path.stat().st_mtime_ns,
    )

    st.image(
        data,
        width=width,
        use_container_width=full_width,
    )


