def sql_df(query, params=()):

    with db.con() as conn:

        return pd.read_sql_query(
            query,
            conn,
            params=params,
        )


def settings(key, default=""):

    try:
        return db.setting(key) or default

    except Exception:
        return default


def fmt(seconds):

    try:

        seconds = float(seconds)

        if (
            not math.isfinite(seconds)
            or seconds < 0
        ):
            return "—"

        minutes = int(seconds // 60)

        return (
            f"{minutes:02d}:"
            f"{seconds - minutes * 60:06.3f}"
        )

    except (TypeError, ValueError):
        return "—"


def get_categories():

    try:
        return db.categories()

    except Exception:
        return pd.DataFrame(
            columns=[
                "name",
                "laps",
                "lap_km",
            ]
        )


def get_athletes():

    try:
        return db.athletes()

    except Exception:
        return pd.DataFrame(
            columns=[
                "id",
                "document",
                "name",
                "category",
                "dorsal",
                "status",
            ]
        )


def get_races():

    try:

        return sql_df(
            """
            SELECT
                id,
                category,
                start_epoch,
                active
            FROM races
            ORDER BY start_epoch, id
            """
        )

    except Exception:

        return pd.DataFrame(
            columns=[
                "id",
                "category",
                "start_epoch",
                "active",
            ]
        )


def get_laps():

    try:

        return sql_df(
            """
            SELECT
                id,
                race_id,
                CAST(dorsal AS TEXT) AS dorsal,
                lap,
                seconds,
                split
            FROM laps
            ORDER BY id
            """
        )

    except Exception:

        return pd.DataFrame(
            columns=[
                "id",
                "race_id",
                "dorsal",
                "lap",
                "seconds",
                "split",
            ]
        )


