def get_results():

    try:
        raw = db.live_results()

    except Exception:
        return pd.DataFrame()

    if raw is None or raw.empty:
        return pd.DataFrame()

    d = raw.copy()

    required = [
        "Salida",
        "Prueba",
        "Dorsal",
        "Corredor",
        "Vueltas",
        "Meta",
        "Segundos",
        "Estado",
    ]

    for col in required:
        if col not in d:
            d[col] = None

    d["Salida"] = pd.to_numeric(
        d["Salida"],
        errors="coerce",
    ).astype("Int64")

    d["Dorsal"] = (
        d["Dorsal"]
        .fillna("")
        .astype(str)
        .str.strip()
    )

    d["Vueltas"] = pd.to_numeric(
        d["Vueltas"],
        errors="coerce",
    ).fillna(0).astype(int)

    d["Meta"] = pd.to_numeric(
        d["Meta"],
        errors="coerce",
    ).fillna(0).astype(int)

    d["Segundos"] = pd.to_numeric(
        d["Segundos"],
        errors="coerce",
    )

    # Evitar duplicados dentro de la misma salida.
    d = (
        d.sort_values(
            ["Vueltas", "Segundos"],
            ascending=[False, True],
            na_position="last",
        )
        .drop_duplicates(
            ["Salida", "Dorsal"]
        )
        .copy()
    )

    cats = get_categories()

    mapping = {}

    if {"name", "laps"}.issubset(cats.columns):

        mapping = dict(
            zip(
                cats["name"].astype(str),
                pd.to_numeric(
                    cats["laps"],
                    errors="coerce",
                ).fillna(0).astype(int),
            )
        )

    def needed(row):

        value = mapping.get(
            str(row["Prueba"]),
            0,
        )

        if value > 0:
            return value

        category = str(row["Prueba"]).lower()

        if "relevo" in category:
            return 4

        if "5k" in category or "5 km" in category:
            return 5

        if "3k" in category or "3 km" in category:
            return 3

        return max(
            1,
            int(row["Vueltas"]),
        )

    d["Requeridas"] = d.apply(
        needed,
        axis=1,
    )

    def state(row):

        status = str(row["Estado"]).upper()

        if status in ("DQ", "DESCALIFICADO"):
            return "DQ"

        if status in ("RETIRADO", "DNF"):
            return "Retirado"

        if (
            row["Meta"] > 0
            or row["Vueltas"] >= row["Requeridas"]
        ):
            return "Completado"

        if row["Vueltas"] > 0:
            return "En carrera"

        return "Por empezar"

    d["Estado carrera"] = d.apply(
        state,
        axis=1,
    )

    d["Faltantes"] = (
        d["Requeridas"] - d["Vueltas"]
    ).clip(lower=0)

    d["Tiempo total"] = d["Segundos"].map(fmt)

    laps = get_laps()

    if not laps.empty:

        laps["race_id"] = pd.to_numeric(
            laps["race_id"],
            errors="coerce",
        ).astype("Int64")

        laps["dorsal"] = (
            laps["dorsal"]
            .astype(str)
            .str.strip()
        )

        laps["lap"] = pd.to_numeric(
            laps["lap"],
            errors="coerce",
        )

        laps["split"] = pd.to_numeric(
            laps["split"],
            errors="coerce",
        )

        laps = laps.drop_duplicates(
            ["race_id", "dorsal", "lap"],
            keep="last",
        )

        laps = laps[
            laps["lap"].between(1, 5)
        ]

        if not laps.empty:

            pivot = laps.pivot(
                index=["race_id", "dorsal"],
                columns="lap",
                values="split",
            ).reset_index()

            pivot = pivot.rename(
                columns={
                    key: f"_lap_{int(key)}"
                    for key in pivot.columns
                    if isinstance(key, (float, int))
                }
            )

            d = d.merge(
                pivot,
                left_on=["Salida", "Dorsal"],
                right_on=["race_id", "dorsal"],
                how="left",
            )

    for i in range(1, 6):

        col = f"_lap_{i}"

        d[f"Vuelta {i}"] = (
            d[col].map(fmt)
            if col in d
            else "—"
        )

    return d.reset_index(drop=True)


def rank(d):

    if d.empty:
        return d.copy()

    out = d.copy()

    priorities = {
        "Completado": 0,
        "En carrera": 1,
        "Por empezar": 2,
        "Retirado": 3,
        "DQ": 4,
    }

    out["_p"] = (
        out["Estado carrera"]
        .map(priorities)
        .fillna(5)
    )

    out["_t"] = (
        out["Segundos"]
        .fillna(float("inf"))
    )

    out = out.sort_values(
        [
            "_p",
            "Vueltas",
            "_t",
            "Corredor",
        ],
        ascending=[
            True,
            False,
            True,
            True,
        ],
        kind="stable",
    ).reset_index(drop=True)

    out["Posición"] = range(
        1,
        len(out) + 1,
    )

    return out


