# CLASIFICACIÓN HTML
# ============================================================

def status_html(state):

    kinds = {
        "Completado": ("done", "✓ Completado"),
        "En carrera": ("run", "▶ En carrera"),
        "Por empezar": ("wait", "◷ Por empezar"),
        "Retirado": ("out", "Retirado"),
        "DQ": ("out", "DQ"),
    }

    css, label = kinds.get(
        state,
        ("wait", str(state)),
    )

    return (
        f'<span class="ud-state {css}">'
        f"{e(label)}</span>"
    )


def leaderboard_html(d, show_position=True):

    cols = [
        "Pos.",
        "Dorsal",
        "Corredor",
        "Prueba",
        "Vuelta 1",
        "Vuelta 2",
        "Vuelta 3",
        "Vuelta 4",
        "Vuelta 5",
        "Estado",
        "Vueltas",
        "Faltantes",
        "Tiempo total",
    ]

    header = "".join(
        f"<th>{e(col)}</th>"
        for col in cols
    )

    rows = []

    for _, row in d.iterrows():

        position = (
            str(row["Posición"])
            if show_position
            else "—"
        )

        cells = [
            f"<td>{e(position)}</td>",
            (
                '<td><span class="ud-bib-pill">'
                f'{e(row["Dorsal"])}'
                "</span></td>"
            ),
            (
                '<td class="ud-name">'
                f'{e(row["Corredor"])}'
                "</td>"
            ),
            f'<td>{e(row["Prueba"])}</td>',
        ]

        for i in range(1, 6):

            cells.append(
                '<td class="ud-lap">'
                f'{e(row[f"Vuelta {i}"])}'
                "</td>"
            )

        cells.extend(
            [
                (
                    "<td>"
                    + status_html(row["Estado carrera"])
                    + "</td>"
                ),
                (
                    f'<td>{int(row["Vueltas"])}'
                    f'/{int(row["Requeridas"])}</td>'
                ),
                f'<td>{int(row["Faltantes"])}</td>',
                (
                    '<td class="ud-total">'
                    f'{e(row["Tiempo total"])}'
                    "</td>"
                ),
            ]
        )

        rows.append(
            "<tr>"
            + "".join(cells)
            + "</tr>"
        )

    markup = (
        '<div class="ud-table-wrap">'
        '<table class="ud-table">'
        "<thead><tr>"
        + header
        + "</tr></thead><tbody>"
        + "".join(rows)
        + "</tbody></table></div>"
    )

    show_html(markup)


