def detail(d):

    if d.empty:
        return

    options = list(range(len(d)))

    selected = st.selectbox(
        "Selecciona un corredor",
        options,
        format_func=lambda i: (
            f'Salida #{d.iloc[i]["Salida"]} · '
            f'Dorsal {d.iloc[i]["Dorsal"]} · '
            f'{d.iloc[i]["Corredor"]}'
        ),
        key="detail_select",
    )

    row = d.iloc[selected]

    a, b, c = st.columns(3)

    a.metric(
        "Dorsal",
        row["Dorsal"],
    )

    b.metric(
        "Vueltas",
        (
            f'{int(row["Vueltas"])}'
            f'/{int(row["Requeridas"])}'
        ),
    )

    c.metric(
        "Tiempo",
        row["Tiempo total"],
    )

    st.markdown(
        f'**{row["Corredor"]}** · '
        f'{row["Prueba"]} · '
        f'{row["Estado carrera"]}'
    )

    laps = get_laps()

    if laps.empty:
        st.info("Sin vueltas registradas.")
        return

    laps["race_id"] = pd.to_numeric(
        laps["race_id"],
        errors="coerce",
    )

    laps["dorsal"] = (
        laps["dorsal"]
        .astype(str)
        .str.strip()
    )

    selected_laps = laps[
        (laps["race_id"] == row["Salida"])
        & (
            laps["dorsal"]
            == str(row["Dorsal"])
        )
    ]

    selected_laps = (
        selected_laps
        .sort_values("id")
        .drop_duplicates(
            "lap",
            keep="last",
        )
        .sort_values("lap")
    )

    if selected_laps.empty:

        st.info(
            "Este corredor todavía no tiene parciales."
        )

        return

    selected_laps = selected_laps.copy()

    selected_laps["Vuelta"] = (
        selected_laps["lap"].astype(int)
    )

    selected_laps["Parcial"] = (
        selected_laps["split"].map(fmt)
    )

    selected_laps["Acumulado"] = (
        selected_laps["seconds"].map(fmt)
    )

    st.dataframe(
        selected_laps[
            [
                "Vuelta",
                "Parcial",
                "Acumulado",
            ]
        ],
        hide_index=True,
        use_container_width=True,
    )

    chart = selected_laps[
        ["lap", "split"]
    ].copy()

    chart["split"] = pd.to_numeric(
        chart["split"],
        errors="coerce",
    )

    chart = chart.dropna()

    if not chart.empty:

        st.bar_chart(
            chart.set_index("lap")["split"],
            x_label="Vuelta",
            y_label="Segundos",
            color="#922343",
        )


